// Task adapter host; original MillSimSharp DLL unchanged. No product tool registration.
using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Numerics;using System.Runtime.InteropServices;using System.Security.Cryptography;using System.Text;using System.Text.Json;using MillSimSharp.Geometry;using MillSimSharp.Simulation;using MillSimSharp.Toolpath;using MillSimSharp.IO;
public static class CADStockTrialHost {
 const string Pin="3cdd4f54ef94e6b95f2a149dad246b4e73aad4e9";
 static volatile bool cancelled;static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
 static Vector3 V(JsonElement e){var a=e.EnumerateArray().Select(x=>x.GetSingle()).ToArray();if(a.Length!=3||a.Any(x=>!float.IsFinite(x)))throw new ArgumentException("finite XYZ required");return new(a[0],a[1],a[2]);}
 static void Check(){if(cancelled)throw new OperationCanceledException();}
 static string Safe(string root,string rel){if(Path.IsPathRooted(rel))throw new ArgumentException("relative path required");string full=Path.GetFullPath(Path.Combine(root,rel));if(!full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.Ordinal))throw new ArgumentException("outside owned workspace");for(var p=new FileInfo(full) as FileSystemInfo;p!=null&&p.FullName!=root;p=p is DirectoryInfo d?d.Parent:p is FileInfo f?f.Directory:null)if(p.LinkTarget!=null)throw new ArgumentException("symlink input refused");return full;}
 static (Vector3 min,Vector3 max) MeshBounds(string p){using var r=new BinaryReader(File.OpenRead(p));if(r.ReadUInt32()!=0x4F533344)throw new ArgumentException("invalid mesh blob");uint version=r.ReadUInt32();if(version!=1&&version!=2)throw new ArgumentException("requires native mesh blob v1");uint n=r.ReadUInt32(),idx=r.ReadUInt32();if(n==0||n>1000000||idx%3!=0||idx>3000000||r.BaseStream.Length!=16L+(version==2?32L:24L)*n+4L*idx)throw new ArgumentException("mesh bounds budget/corruption");var min=new Vector3(float.PositiveInfinity);var max=new Vector3(float.NegativeInfinity);for(int i=0;i<n;i++){var v=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());if(!float.IsFinite(v.X)||!float.IsFinite(v.Y)||!float.IsFinite(v.Z))throw new ArgumentException("nonfinite mesh");min=Vector3.Min(min,v);max=Vector3.Max(max,v);}r.BaseStream.Position=16+24L*n;for(int i=0;i<idx;i++)if(r.ReadUInt32()>=n)throw new ArgumentException("bad native mesh indices");return(min,max);}
 public static int Main(string[] args){try{return Run(args);}catch(Exception e){Console.Error.WriteLine(e);return e is OperationCanceledException?130:1;}}
 static int Run(string[] args){
  if(!RuntimeInformation.IsOSPlatform(OSPlatform.OSX)||RuntimeInformation.ProcessArchitecture!=Architecture.Arm64)throw new PlatformNotSupportedException("This candidate is qualified only for arm64 macOS; no iOS/Linux/riscv fallback");
  if(args.Length==3 && args[0]=="--promote-directory") {
   string from=Path.GetFullPath(args[1]),to=Path.GetFullPath(args[2]);
   if(Path.GetDirectoryName(from)!=Path.GetDirectoryName(to)||!Path.GetFileName(from).Contains(".pending-")||!Directory.Exists(from))throw new ArgumentException("invalid managed resource promotion");
   if(Directory.Exists(to))return 2;Directory.Move(from,to);return 0;
  }
  if(args.Length!=4)throw new ArgumentException("workspace input-relative.json output-relative-directory expected-input-sha256");string root=Path.GetFullPath(args[0]);string inputPath=Safe(root,args[1]);string output=Safe(root,args[2]);if(Directory.Exists(output)||File.Exists(output))throw new IOException("never reuse an output; inspect the existing owned job");
  Console.CancelKeyPress+=(_,e)=>{e.Cancel=true;cancelled=true;};using var timeout=new System.Threading.Timer(_=>cancelled=true,null,30000,System.Threading.Timeout.Infinite);
  if(Hash(inputPath)!=args[3])throw new ArgumentException("input changed after submission");
  if(new FileInfo(inputPath).Length>128000)throw new ArgumentException("input budget");using var doc=JsonDocument.Parse(File.ReadAllBytes(inputPath));var q=doc.RootElement;if(q.GetProperty("schema").GetString()!="floe.cad-stock-task.v1"||q.GetProperty("units").GetString()!="mm")throw new ArgumentException("unsupported schema/units");
  var source=q.GetProperty("source");var originals=new Dictionary<string,string>();foreach(var file in source.GetProperty("files").EnumerateArray()){string rel=file.GetProperty("path").GetString()!;string full=Safe(root,rel),expected=file.GetProperty("sha256").GetString()!;if(new FileInfo(full).Length>16000000||Hash(full)!=expected)throw new ArgumentException("source digest mismatch");originals.Add(rel,expected);}if(originals.Count!=4)throw new ArgumentException("four source snapshot members required");
  string baseRel=source.GetProperty("snapshotRoot").GetString()!;string model=Safe(root,baseRel+"/document.json"),manifest=Safe(root,baseRel+"/manifest.json");using var mdoc=JsonDocument.Parse(File.ReadAllBytes(model));using var md=JsonDocument.Parse(File.ReadAllBytes(manifest));string bodyID=source.GetProperty("bodyID").GetString()!;
  if(md.RootElement.GetProperty("revision").GetInt64()!=source.GetProperty("documentRevision").GetInt64()||md.RootElement.GetProperty("modelSHA256").GetString()!=source.GetProperty("modelSHA256").GetString()||md.RootElement.GetProperty("unit").GetString()!="mm")throw new ArgumentException("stale source document");
  var body=mdoc.RootElement.GetProperty("bodies").EnumerateArray().Single(b=>b.GetProperty("bodyID").GetString()==bodyID);using var transform=JsonDocument.Parse(Convert.FromBase64String(body.GetProperty("transform").GetString()!));var t=transform.RootElement;
  if(V(t.GetProperty("translation"))!=Vector3.Zero||t.GetProperty("scale").GetSingle()!=1||!t.GetProperty("rotation").EnumerateArray().Select(x=>x.GetSingle()).SequenceEqual(new float[]{0,0,0,1}))throw new ArgumentException("bounded stock adapter requires identity part placement");
  string meshRel=baseRel+"/"+body.GetProperty("meshBlob").GetString()!,brepRel=baseRel+"/"+body.GetProperty("brepBlob").GetString()!;if(!originals.TryGetValue(meshRel,out var mh)||mh!=body.GetProperty("meshSHA256").GetString()||!originals.TryGetValue(brepRel,out var bh)||bh!=body.GetProperty("brepSHA256").GetString())throw new ArgumentException("selected part cache identity mismatch");
  var bounds=MeshBounds(Safe(root,meshRel));var stock=q.GetProperty("stock");if(stock.GetProperty("mode").GetString()!="part-bounding-box-blank")throw new ArgumentException("only explicit bounding-box blank supported");float h=stock.GetProperty("resolutionMM").GetSingle();if(!float.IsFinite(h)||!(new float[]{.25f,.5f,1f,2f}).Contains(h))throw new ArgumentException("resolution budget");var extent=bounds.max-bounds.min;long cells=(long)Math.Ceiling(extent.X/h)*(long)Math.Ceiling(extent.Y/h)*(long)Math.Ceiling(extent.Z/h);if(cells<=0||cells>2000000||extent.X>1000||extent.Y>1000||extent.Z>1000||new[]{bounds.min.X,bounds.min.Y,bounds.min.Z,bounds.max.X,bounds.max.Y,bounds.max.Z}.Any(v=>MathF.Abs(v)>10000))throw new ArgumentException("stock cell budget");
  var tool=q.GetProperty("tool");if(tool.GetProperty("kind").GetString()!="flat-end-mill")throw new ArgumentException("only flat-end-mill supported");float radius=tool.GetProperty("radiusMM").GetSingle(),length=tool.GetProperty("lengthMM").GetSingle();if(!float.IsFinite(radius)||!float.IsFinite(length)||radius<.1||radius>100||length<.1||length>100)throw new ArgumentException("tool budget");
  var path=q.GetProperty("path");if(path.GetProperty("kind").GetString()!="linear-fixed-z")throw new ArgumentException("only qualified fixed-Z straight cut enabled; rotation remains separate qualification");Vector3 start=V(path.GetProperty("startTipMM")),end=V(path.GetProperty("endTipMM"));if(start.Z!=end.Z||Vector3.Distance(start,end)>100)throw new ArgumentException("path budget or nonperpendicular cut");
  Check();var grid=new VoxelGrid(new BoundingBox(bounds.min,bounds.max),h){UseParallelRemoval=false};var sim=new CutterSimulator(grid);sim.Settings.MaxLinearStep=.25f;sim.Settings.MaxAngularStep=.125f;sim.Settings.MaxChordError=.001f;var ex=new ToolpathExecutor(sim,new EndMill(radius*2,length,false),start,ToolOrientation.Default);ex.ExecuteCommands(new IToolpathCommand[]{new G1Move5Axis(end,ToolOrientation.Default,100)});Check();
  long faces=0;var checkDims=grid.Dimensions;
  for(int z=0;z<checkDims.Z;z++){Check();for(int y=0;y<checkDims.Y;y++)for(int x=0;x<checkDims.X;x++)if(grid.GetVoxel(x,y,z)){
   if(!grid.GetVoxel(x-1,y,z))faces++;if(!grid.GetVoxel(x+1,y,z))faces++;
   if(!grid.GetVoxel(x,y-1,z))faces++;if(!grid.GetVoxel(x,y+1,z))faces++;
   if(!grid.GetVoxel(x,y,z-1))faces++;if(!grid.GetVoxel(x,y,z+1))faces++;
