  }}
  string staging=output+".pending-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(staging);StlExporter.Export(grid,Path.Combine(staging,"stock.stl"));var dims=grid.Dimensions;using(var w=new BinaryWriter(File.Create(Path.Combine(staging,"stock.occupancy")))){w.Write(Encoding.ASCII.GetBytes("FLSTK001"));w.Write(dims.X);w.Write(dims.Y);w.Write(dims.Z);w.Write(h);w.Write(bounds.min.X);w.Write(bounds.min.Y);w.Write(bounds.min.Z);for(int z=0;z<dims.Z;z++){Check();for(int y=0;y<dims.Y;y++)for(int x=0;x<dims.X;x++)w.Write((byte)(grid.GetVoxel(x,y,z)?1:0));}}
  foreach(var x in originals)if(Hash(Safe(root,x.Key))!=x.Value)throw new IOException("source changed during computation");Check();
  var result=new{schema="floe.cad-stock-result.v1",outcome="computed-not-job-accepted",requestSHA256=Hash(inputPath),ownerBinding=q.GetProperty("ownerBinding").Clone(),ownerBindingVerified=false,source=source.Clone(),sourceUnchanged=true,backend=new{sourcePin=Pin,coreSHA256=Hash(typeof(CutterSimulator).Assembly.Location),wrapperSHA256=Hash(typeof(CADStockTrialHost).Assembly.Location),runtime=Environment.Version.ToString(),actualOS=RuntimeInformation.OSDescription,architecture=RuntimeInformation.ProcessArchitecture.ToString(),transport="not inferred by CLI; join with trusted jobs receipt"},stock=new{mode="part-bounding-box-blank",partIsReferenceOnly=true,resolutionMM=h,gridDimensions=new[]{dims.X,dims.Y,dims.Z},boundsMin=new[]{bounds.min.X,bounds.min.Y,bounds.min.Z},boundsMax=new[]{bounds.max.X,bounds.max.Y,bounds.max.Z},removedMM3=grid.GetRemovedVolume(),remainingMM3=grid.GetMaterialVolume()},precision="center-sampled voxel stock; fixed-Z straight-cut swept solid; mesh approximation, not BRep or machine safety",artifacts=new[]{new{path="stock.stl",sha256=Hash(Path.Combine(staging,"stock.stl")),bytes=new FileInfo(Path.Combine(staging,"stock.stl")).Length},new{path="stock.occupancy",sha256=Hash(Path.Combine(staging,"stock.occupancy")),bytes=new FileInfo(Path.Combine(staging,"stock.occupancy")).Length}}};
  File.WriteAllText(Path.Combine(staging,"manifest.json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Check();Directory.Move(staging,output);Console.WriteLine(JsonSerializer.Serialize(new{outcome=result.outcome,manifest=Path.GetRelativePath(root,Path.Combine(output,"manifest.json")),manifestSHA256=Hash(Path.Combine(output,"manifest.json")),removedMM3=grid.GetRemovedVolume()}));return 0;
 }
